// Capture NDJSON traces ({pre, action, data, post}) from src/host.impl.ts via its inspect() seam.
// Usage: node spec/capture.mjs  -> writes spec/traces/*.ndjson
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost, { inspect } from '../src/host.impl.ts';

const OUT = new URL('./traces/', import.meta.url);
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const keyOf = (m) => `${m.action}|${m.from}|${m.to}`;

async function step(h, lines, action, data) {
  const pre = inspect(h);
  if (action === 'TIMEOUT') await h.timeout(data.node);
  else {
    const m = (await h.inFlight()).find((x) => keyOf(x) === data.msg);
    await h.deliver(m ? m.id : 'absent');
  }
  lines.push(JSON.stringify({ pre, action, data, post: inspect(h) }));
}

// Deterministic pseudo-random scenarios (seeded LCG) plus hand-written ones.
function lcg(seed) {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
}

const ALL_MSGS = [];
for (const a of ['RequestVote', 'VoteReply']) for (const f of ['n0', 'n1', 'n2']) for (const t of ['n0', 'n1', 'n2']) if (f !== t) ALL_MSGS.push(`${a}|${f}|${t}`);

async function scenario(name, plan) {
  const h = await createHost();
  const lines = [];
  await plan(h, (action, data) => step(h, lines, action, data));
  writeFileSync(new URL(`${name}.ndjson`, OUT), lines.join('\n') + '\n');
}

await scenario('single-candidate', async (h, s) => {
  await s('TIMEOUT', { node: 'n0' });
  while ((await h.inFlight()).length) await s('DELIVER', { msg: keyOf((await h.inFlight())[0]) });
  await s('TIMEOUT', { node: 'n0' });
  await s('TIMEOUT', { node: 'n1' });
  await s('TIMEOUT', { node: 'n9' });
  await s('DELIVER', { msg: 'VoteReply|n1|n0' });
});

await scenario('split-vote', async (h, s) => {
  await s('TIMEOUT', { node: 'n0' });
  await s('TIMEOUT', { node: 'n1' });
  await s('TIMEOUT', { node: 'n2' });
  while ((await h.inFlight()).length) await s('DELIVER', { msg: keyOf((await h.inFlight())[0]) });
});

for (let seed = 1; seed <= 40; seed++) {
  await scenario(`random-${seed}`, async (h, s) => {
    const rnd = lcg(seed);
    for (let i = 0; i < 14; i++) {
      const r = rnd();
      if (r < 0.25) await s('TIMEOUT', { node: ['n0', 'n1', 'n2', 'n9'][Math.floor(rnd() * 4)] });
      else if (r < 0.35) await s('DELIVER', { msg: ALL_MSGS[Math.floor(rnd() * ALL_MSGS.length)] });
      else {
        const f = await h.inFlight();
        if (f.length) await s('DELIVER', { msg: keyOf(f[Math.floor(rnd() * f.length)]) });
      }
    }
  });
}
console.log('traces written');

