import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { check, loadSpec } from '../tools/polygraph/scripts/check.mjs';
import * as invariants from './invariants.mjs';

const src = readFileSync(new URL('./election.spec.cjs', import.meta.url), 'utf-8');
const contract = JSON.parse(readFileSync(new URL('./contract.json', import.meta.url), 'utf-8'));
const dir = mkdtempSync(join(tmpdir(), 'election-mutants-'));

const MUTANTS = {
  'grant-to-anyone': ["granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);", 'granted = true;'],
  'revote-overwrites': ['if (granted) updated = { ...n, votedFor: candidate };', 'updated = { ...n, votedFor: candidate }; granted = true;'],
  'count-denied-replies': ["|| data.granted !== true) return unchanged('nodes');", ") return unchanged('nodes');"],
  'majority-of-one': ['votes.length >= MAJORITY', 'votes.length >= 1'],
  'timeout-anytime': ["if (n.role !== 'follower' || n.term !== 0) return reject('timeout-only-from-term0-follower');", "if (n.role === 'leader') return reject('timeout-only-from-term0-follower');"],
};

let failed = 0;
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!src.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const file = join(dir, `${name}.cjs`);
  writeFileSync(file, src.replace(from, to));
  const r = check({ specModule: loadSpec(file), contract, invariants });
  const names = [...new Set((r.violations || []).map((v) => v.invariant || v.name))];
  console.log(`${names.length ? 'caught ' : 'MISSED '} ${name}${names.length ? ': ' + names.join(', ') : ''}`);
  if (!names.length) failed++;
}
process.exit(failed ? 1 : 0);

