  // a follower already moved to term 1 by a vote request cannot start an election
  const [m] = before.filter((x) => x.to === 'n1');
  await h.deliver(m.id);
  assert.equal((await h.timeout('n1')).ok, false);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
});

test('single candidate wins with deliverAll', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.inFlight(), []);
});

test('a new leader announces itself to the other two', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const rv = (await h.inFlight()).find((m) => m.to === 'n1');
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply');
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const announces = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(announces.map((m) => m.to).sort(), ['n1', 'n2']);
