// Exhaustive exploration over every interleaving of timeouts and deliveries.
async function replay(steps) {
  const h = await createHost();
  for (const s of steps) {
    if (s.t === 'timeout') await h.timeout(s.node);
    else {
      const m = (await h.inFlight()).find((x) => x.from === s.from && x.to === s.to && x.action === s.action);
      await h.deliver(m.id);
    }
  }
  return h;
}

test('every interleaving: at most one leader, leader has a majority, no double votes', async () => {
  const seen = new Set();
  let explored = 0;
  const stack = [[]];
  while (stack.length) {
    const steps = stack.pop();
    const h = await replay(steps);
    const views = {};
    for (const n of NODES) views[n] = await h.node(n);
    const flight = await h.inFlight();
    const key = JSON.stringify([views, flight.map((m) => [m.from, m.to, m.action, m.data]).sort()]);
    if (seen.has(key)) continue;
    seen.add(key);
    explored++;
    const leaders = NODES.filter((n) => views[n].role === 'leader');
    assert.ok(leaders.length <= 1, key);
    for (const l of leaders) {
      const voters = NODES.filter((n) => views[n].term === 1 && views[n].votedFor === l);
      assert.ok(voters.length >= 2, key);
    }
    for (const n of NODES) {
      if (views[n].role !== 'follower') assert.equal(views[n].votedFor, n, key);
    }
    for (const n of NODES) if (views[n].role === 'follower' && views[n].term === 0) stack.push([...steps, { t: 'timeout', node: n }]);
    for (const m of flight) stack.push([...steps, { t: 'deliver', from: m.from, to: m.to, action: m.action }]);
  }
  assert.ok(explored > 100);
});

'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts: three nodes, one election (term 1).
// State: nodes (id -> { role, term, votedFor, votes }) and net (in-flight messages,
// keyed "<action>|<from>|<to>" — each such message is sent at most once).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const TERM = 1;
const MAJORITY = 2;

const follower0 = () => ({ role: 'follower', term: 0, votedFor: null, votes: [] });
const INITIAL_STATE = { nodes: { n0: follower0(), n1: follower0(), n2: follower0() }, net: {} };

const MSG_KEYS = [];
for (const action of ['RequestVote', 'VoteReply']) {
  for (const from of NODES) for (const to of NODES) if (from !== to) MSG_KEYS.push(`${action}|${from}|${to}`);
}

const withoutKey = (obj, k) => {
  const out = { ...obj };
  delete out[k];
  return out;
};

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      nodes: { type: 'object' },
      net: { type: 'object' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: ['n0', 'n1', 'n2', 'n9'].map((node) => ({ node })),
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MSG_KEYS.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next }) => {
        const id = proposal.node;
        if (!NODES.includes(id)) return reject('timeout-unknown-node');
        const n = model.nodes[id];
        if (n.role !== 'follower' || n.term !== 0) return reject('timeout-only-from-term0-follower');
        next.nodes = { ...model.nodes, [id]: { role: 'candidate', term: TERM, votedFor: id, votes: [id] } };
        const net = { ...model.net };
        for (const other of NODES) if (other !== id) net[`RequestVote|${id}|${other}`] = { from: id, term: TERM };
        next.net = net;
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const key = proposal.msg;
        const data = model.net[key];
        if (data === undefined) return reject('not-in-flight');
        const [action, from, to] = key.split('|');
        let net = withoutKey(model.net, key);
        const n = model.nodes[to];
        if (action === 'RequestVote') {
          const candidate = data.from;
          if (data.term !== TERM || !NODES.includes(candidate)) {
            next.net = net;
            return unchanged('nodes');
          }
          let granted;
          let updated = n;
          if (n.term < TERM) {
            updated = { ...n, role: 'follower', term: TERM, votedFor: candidate };
            granted = true;
          } else {
            granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);
            if (granted) updated = { ...n, votedFor: candidate };
          }
          net = { ...net, [`VoteReply|${to}|${candidate}`]: { term: TERM, granted } };
          next.nodes = { ...model.nodes, [to]: updated };
          next.net = net;
          return;
        }
        // VoteReply
        next.net = net;
        if (n.role !== 'candidate' || data.term !== n.term || data.granted !== true) return unchanged('nodes');
        const votes = [...new Set([...n.votes, from])].sort();
        const role = votes.length >= MAJORITY ? 'leader' : n.role;
        next.nodes = { ...model.nodes, [to]: { ...n, votes, role } };
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };

const init = () => { setState(JSON.parse(JSON.stringify(INITIAL_STATE))); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

