// Rules the brief requires, as predicates over the spec state { nodes, net }.
const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leadersIn = (s, term) => NODES.filter((id) => s.nodes[id].role === 'leader' && s.nodes[id].term === term);
const votersFor = (s, c, term) => NODES.filter((id) => s.nodes[id].term === term && s.nodes[id].votedFor === c);

export const stateInvariants = [
  {
    name: 'at-most-one-leader-per-term',
    pred: (s) => [0, 1].every((t) => leadersIn(s, t).length <= 1),
  },
  {
    name: 'leader-holds-majority-of-votes',
    pred: (s) => NODES.every((id) => s.nodes[id].role !== 'leader' || votersFor(s, id, s.nodes[id].term).length >= MAJORITY),
  },
  {
    name: 'counted-votes-are-real-votes',
    // every vote a candidate/leader counted came from a node that voted for it in that term
    pred: (s) => NODES.every((id) => s.nodes[id].votes.every((v) => s.nodes[v].term === s.nodes[id].term && s.nodes[v].votedFor === id)),
  },
  {
    name: 'candidates-and-leaders-vote-for-themselves',
    pred: (s) => NODES.every((id) => s.nodes[id].role === 'follower' || s.nodes[id].votedFor === id),
  },
  {
    name: 'terms-stay-in-0-or-1',
    pred: (s) => NODES.every((id) => s.nodes[id].term === 0 || s.nodes[id].term === 1),
  },
  {
    name: 'term-0-nodes-have-no-vote',
    pred: (s) => NODES.every((id) => s.nodes[id].term !== 0 || (s.nodes[id].votedFor === null && s.nodes[id].role === 'follower')),
  },
  {
    name: 'a-leader-knows-itself',
    pred: (s) => NODES.every((id) => s.nodes[id].role !== 'leader' || s.nodes[id].leader === id),
  },
  {
    name: 'known-leader-is-the-leader-of-that-term',
    pred: (s) =>
      NODES.every((id) => {
        const l = s.nodes[id].leader;
        return l === null || (s.nodes[id].term === 1 && s.nodes[l].role === 'leader' && s.nodes[l].term === s.nodes[id].term);
      }),
  },
  {
    name: 'candidates-know-no-leader',
    pred: (s) => NODES.every((id) => s.nodes[id].role !== 'candidate' || s.nodes[id].leader === null),
  },
  {
    name: 'leader-is-never-sent-leader',
    pred: (s) => Object.keys(s.net).every((k) => {
      const [action, , to] = k.split('|');
      return action !== 'Leader' || s.nodes[to].role !== 'leader';
    }),
  },
  {
    name: 'only-the-leader-announces',
    pred: (s) => Object.keys(s.net).every((k) => {
      const [action, from] = k.split('|');
      return action !== 'Leader' || s.nodes[from].role === 'leader';
    }),
  },
];

export const transitionInvariants = [
  {
    name: 'no-node-votes-twice-in-a-term',
    // once a node has a vote in a term, it never changes while the term stays the same
    pred: (pre, _a, _d, post) =>
      NODES.every((id) => {
        const a = pre.nodes[id];
        const b = post.nodes[id];
        return a.votedFor === null || a.term !== b.term || a.votedFor === b.votedFor;
      }),
  },
  {
    name: 'terms-never-decrease',
    pred: (pre, _a, _d, post) => NODES.every((id) => post.nodes[id].term >= pre.nodes[id].term),
  },
  {
    name: 'leaders-stay-leaders',
    pred: (pre, _a, _d, post) => NODES.every((id) => pre.nodes[id].role !== 'leader' || post.nodes[id].role === 'leader'),
  },
  {
    name: 'refused-timeout-changes-nothing',
    pred: (pre, action, data, post) => {
      if (action !== 'TIMEOUT') return true;
      const n = pre.nodes[data.node];
      const allowed = n && n.role === 'follower' && n.term === 0;
      return allowed || JSON.stringify(pre) === JSON.stringify(post);
    },
  },
];

export default { stateInvariants, transitionInvariants };

