async function replay(steps) {
  const h = await createHost();
  for (const s of steps) {
    if (s.t === 'timeout') await h.timeout(s.node);
    else if (s.t === 'giveUp') await h.giveUp(s.node);
    else {
      const m = (await h.inFlight()).find((x) => x.from === s.from && x.to === s.to && x.action === s.action);
      await h.deliver(m.id);
    }
  }
  return h;
}

test('every interleaving: at most one leader, leader has a majority, no double votes', async () => {
  const seen = new Set();
  let explored = 0;
  const stack = [[]];
  while (stack.length) {
    const steps = stack.pop();
    const h = await replay(steps);
    const views = {};
    for (const n of NODES) views[n] = await h.node(n);
    const flight = await h.inFlight();
    const key = JSON.stringify([views, flight.map((m) => [m.from, m.to, m.action, m.data]).sort()]);
    if (seen.has(key)) continue;
    seen.add(key);
    explored++;
    const leaders = NODES.filter((n) => views[n].role === 'leader');
    assert.ok(leaders.length <= 1, key);
    for (const l of leaders) {
      const voters = NODES.filter((n) => views[n].term === 1 && views[n].votedFor === l);
      assert.ok(voters.length >= 2, key);
    }
    for (const n of NODES) {
      if (views[n].role !== 'follower') assert.equal(views[n].votedFor, n, key);
      if (views[n].role === 'leader') assert.equal(views[n].leader, n, key);
      if (views[n].leader !== null) {
        assert.equal(views[views[n].leader].role, 'leader', key);
        assert.equal(views[n].term, 1, key);
      }
    }
    assert.ok(!flight.some((m) => m.action === 'Leader' && views[m.to].role === 'leader'), key);
    for (const n of NODES) if (views[n].role === 'follower' && views[n].term === 0) stack.push([...steps, { t: 'timeout', node: n }]);
    for (const n of NODES) if (views[n].role === 'candidate') stack.push([...steps, { t: 'giveUp', node: n }]);
    for (const m of flight) stack.push([...steps, { t: 'deliver', from: m.from, to: m.to, action: m.action }]);
  }
  assert.ok(explored > 100);
});

