import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: followers in term 0, no vote, nothing in flight', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends RequestVote to the other two', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
});

test('timeout refusals change nothing', async () => {
  const h = await createHost();
  assert.equal((await h.timeout('n9')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.timeout('n0');
  const before = await h.inFlight();
  const r = await h.timeout('n0');
  assert.equal(r.ok, false);
  assert.equal(typeof r.reason, 'string');
  assert.deepEqual(await h.inFlight(), before);
  // a follower already moved to term 1 by a vote request cannot start an election
  const [m] = before.filter((x) => x.to === 'n1');
  await h.deliver(m.id);
  assert.equal((await h.timeout('n1')).ok, false);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
});

test('single candidate wins with deliverAll', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.inFlight(), []);
});

test('a new leader announces itself to the other two', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const rv = (await h.inFlight()).find((m) => m.to === 'n1');
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply');
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const announces = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(announces.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of announces) {
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
});

test('Leader moves a term-0 node to term 1 without a vote, and a candidate steps down', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  // n2 votes for n0 first; n0 wins; n1 stays a candidate until the announcement arrives
  const toN2 = (await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n2');
  await h.deliver(toN2.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply' && m.to === 'n0');
  await h.deliver(reply.id);
  const toN1 = (await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n1');
  await h.deliver(toN1.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n0' });

  const h2 = await createHost();
  await h2.timeout('n0');
  await h2.deliver((await h2.inFlight()).find((m) => m.to === 'n1').id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'VoteReply').id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2').id);
  assert.deepEqual(await h2.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h2.timeout('n2')).ok, false);
});

test('giveUp: a candidate becomes a follower, keeps its vote, ignores later replies', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false); // a follower cannot give up
  assert.equal((await h.giveUp('n7')).ok, false);
  await h.timeout('n0');
  await h.timeout('n1');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  const again = await h.giveUp('n0');
  assert.equal(again.ok, false);
  assert.equal(typeof again.reason, 'string');
  assert.equal((await h.timeout('n0')).ok, false);
  // n0 denies n1; n2 grants n0 but n0 ignores it; n2 is taken so n1 cannot win either
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n2').id);
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0').id);
  assert.deepEqual((await h.inFlight()).find((m) => m.action === 'VoteReply' && m.to === 'n1' && m.from === 'n0').data, { term: 1, granted: false });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.node('n1')).role, 'candidate');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
});

test('a candidate that gave up learns the leader another node won', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  await h.giveUp('n0');
  await h.deliverAll();
  // n2 may have voted for n0 or n1 depending on order; n1 wins only if n2 voted for it
  const n1 = await h.node('n1');
  if (n1.role === 'leader') assert.equal((await h.node('n0')).leader, 'n1');
  assert.equal((await h.node('n0')).role, 'follower');
});

test('leader cannot give up', async () => {
  const h = await createHost();
  await h.timeout('n2');
  await h.deliverAll();
  assert.equal((await h.giveUp('n2')).ok, false);
  assert.equal((await h.node('n2')).role, 'leader');
});

test('vote replies carry term and granted; a candidate denies other candidates', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1');
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply');
  assert.deepEqual(reply, { id: reply.id, from: 'n1', to: 'n0', action: 'VoteReply', data: { term: 1, granted: false } });
  await h.deliver(reply.id);
  assert.equal((await h.node('n0')).role, 'candidate');
});

test('deliver of an unknown id does nothing', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver('nope');
  assert.equal((await h.inFlight()).length, 2);
});

// Exhaustive exploration over every interleaving of timeouts and deliveries.
async function replay(steps) {
  const h = await createHost();
  for (const s of steps) {
    if (s.t === 'timeout') await h.timeout(s.node);
