// Exhaustive exploration over every interleaving of commands and deliveries.
async function replay(steps) {
  const h = await createHost();
  for (const s of steps) {
    if (s.t === 'deliver') {
      const m = (await h.inFlight()).find((x) => x.from === s.from && x.to === s.to && x.action === s.action);
      await h.deliver(m.id);
    } else await h[s.t](s.node);
  }
  return h;
}

test('every interleaving: at most one leader, leader has a majority, no double votes', async () => {
  const seen = new Set();
  let explored = 0;
  const stack = [{ steps: [], parent: null }];
  while (stack.length) {
    const { steps, parent } = stack.pop();
    const h = await replay(steps);
    const views = {};
    for (const n of NODES) views[n] = await h.node(n);
    const flight = await h.inFlight();
    // no node votes twice in a term (checked on every edge, before dedup)
    if (parent) {
      for (const n of NODES) {
        const a = parent[n];
        if (a.votedFor !== null && a.term === views[n].term) assert.equal(views[n].votedFor, a.votedFor, JSON.stringify(steps));
      }
    }
    const key = JSON.stringify(inspect(h));
    if (seen.has(key)) continue;
    seen.add(key);
    explored++;
    const elected = (l) => views[l].votedFor === l && NODES.filter((n) => views[n].term === 1 && views[n].votedFor === l).length >= 2;
    const leaders = NODES.filter((n) => views[n].role === 'leader');
    assert.ok(leaders.length <= 1, key);
    for (const l of leaders) assert.ok(elected(l), key);
    const known = new Set(NODES.map((n) => views[n].leader).filter((l) => l !== null));
    assert.ok(known.size <= 1, key);
    for (const n of NODES) {
      if (views[n].role === 'candidate' || views[n].role === 'leader') assert.equal(views[n].votedFor, n, key);
      if (views[n].role === 'leader') assert.equal(views[n].leader, n, key);
      if (views[n].leader !== null) {
        assert.ok(elected(views[n].leader), key);
        assert.equal(views[n].term, 1, key);
      }
    }
    assert.ok(!flight.some((m) => m.action === 'Leader' && views[m.to].role === 'leader'), key);
    const push = (s) => stack.push({ steps: [...steps, s], parent: views });
    for (const n of NODES) {
      if (views[n].role === 'follower' && views[n].term === 0) push({ t: 'timeout', node: n });
      if (views[n].role === 'candidate') push({ t: 'giveUp', node: n });
      push({ t: views[n].role === 'down' ? 'recover' : 'crash', node: n });
    }
    for (const m of flight) push({ t: 'deliver', from: m.from, to: m.to, action: m.action });
  }
  assert.ok(explored > 100);
});

