'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts: three nodes, one election (term 1).
// State: nodes (id -> { role, term, votedFor, leader, votes }) and net (in-flight messages,
// keyed "<action>|<from>|<to>" — each such message is sent at most once).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const TERM = 1;
const MAJORITY = 2;

const follower0 = () => ({ role: 'follower', term: 0, votedFor: null, leader: null, votes: [] });
const INITIAL_STATE = { nodes: { n0: follower0(), n1: follower0(), n2: follower0() }, net: {} };

const MSG_KEYS = [];
for (const action of ['RequestVote', 'VoteReply', 'Leader']) {
  for (const from of NODES) for (const to of NODES) if (from !== to) MSG_KEYS.push(`${action}|${from}|${to}`);
}

const withoutKey = (obj, k) => {
  const out = { ...obj };
  delete out[k];
  return out;
};

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      nodes: { type: 'object' },
      net: { type: 'object' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: ['n0', 'n1', 'n2', 'n9'].map((node) => ({ node })),
      },
      GIVE_UP: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: ['n0', 'n1', 'n2', 'n9'].map((node) => ({ node })),
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MSG_KEYS.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next }) => {
        const id = proposal.node;
        if (!NODES.includes(id)) return reject('timeout-unknown-node');
        const n = model.nodes[id];
        if (n.role !== 'follower' || n.term !== 0) return reject('timeout-only-from-term0-follower');
        next.nodes = { ...model.nodes, [id]: { role: 'candidate', term: TERM, votedFor: id, leader: null, votes: [id] } };
        const net = { ...model.net };
        for (const other of NODES) if (other !== id) net[`RequestVote|${id}|${other}`] = { from: id, term: TERM };
        next.net = net;
      },
      GIVE_UP: (model) => (proposal, { reject, next, unchanged }) => {
        const id = proposal.node;
        if (!NODES.includes(id)) return reject('give-up-unknown-node');
        if (model.nodes[id].role !== 'candidate') return reject('give-up-only-candidate');
        // same term, keeps its vote for itself
        next.nodes = { ...model.nodes, [id]: { ...model.nodes[id], role: 'follower' } };
        unchanged('net');
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const key = proposal.msg;
        const data = model.net[key];
        if (data === undefined) return reject('not-in-flight');
        const [action, from, to] = key.split('|');
        let net = withoutKey(model.net, key);
        const n = model.nodes[to];
        if (action === 'RequestVote') {
          const candidate = data.from;
          if (data.term !== TERM || !NODES.includes(candidate)) {
            next.net = net;
            return unchanged('nodes');
          }
          let granted;
          let updated = n;
          if (n.term < TERM) {
            updated = { ...n, role: 'follower', term: TERM, votedFor: candidate };
            granted = true;
          } else {
            granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);
            if (granted) updated = { ...n, votedFor: candidate };
          }
          net = { ...net, [`VoteReply|${to}|${candidate}`]: { term: TERM, granted } };
          next.nodes = { ...model.nodes, [to]: updated };
          next.net = net;
          return;
        }
        if (action === 'Leader') {
          const leader = data.from;
          next.net = net;
          if (data.term !== TERM || !NODES.includes(leader) || n.role === 'leader') return unchanged('nodes');
          // term 0: join term 1 without voting; candidate: step down, keeping its own vote
          const updated = n.term < TERM
            ? { ...n, role: 'follower', term: TERM, votedFor: null, leader }
            : { ...n, role: 'follower', leader };
          next.nodes = { ...model.nodes, [to]: updated };
          return;
        }
        // VoteReply
        if (n.role !== 'candidate' || data.term !== n.term || data.granted !== true) {
          next.net = net;
          return unchanged('nodes');
        }
        const votes = [...new Set([...n.votes, from])].sort();
        if (votes.length < MAJORITY) {
          next.net = net;
          next.nodes = { ...model.nodes, [to]: { ...n, votes } };
          return;
        }
        for (const other of NODES) if (other !== to) net = { ...net, [`Leader|${to}|${other}`]: { from: to, term: n.term } };
        next.net = net;
        next.nodes = { ...model.nodes, [to]: { ...n, votes, role: 'leader', leader: to } };
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };

const init = () => { setState(JSON.parse(JSON.stringify(INITIAL_STATE))); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  GIVE_UP: (data = {}) => intents.GIVE_UP(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

