    name: 'candidates-and-leaders-vote-for-themselves',
    pred: (s) => NODES.every((id) => !['candidate', 'leader'].includes(s.nodes[id].role) || s.nodes[id].votedFor === id),
  },
  {
    name: 'at-most-one-node-ever-elected',
    pred: (s) => NODES.filter((id) => elected(s, id)).length <= 1,
  },
  {
    name: 'down-nodes-hold-no-tally',
    pred: (s) => NODES.every((id) => s.nodes[id].role !== 'down' || s.nodes[id].votes.length === 0),
  },
  {
    name: 'terms-stay-in-0-or-1',
    pred: (s) => NODES.every((id) => s.nodes[id].term === 0 || s.nodes[id].term === 1),
  },
