const keyOf = (m) => `${m.action}|${m.from}|${m.to}`;

async function step(h, lines, action, data) {
  const pre = inspect(h);
  if (action === 'TIMEOUT') await h.timeout(data.node);
  else if (action === 'GIVE_UP') await h.giveUp(data.node);
  else if (action === 'CRASH') await h.crash(data.node);
  else if (action === 'RECOVER') await h.recover(data.node);
