// Negative control for the model check: each mutant breaks one rule of the brief in the spec;
// the invariants must catch every one. Usage: node spec/negative-control.mjs
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { check, loadSpec } from '../tools/polygraph/scripts/check.mjs';
import * as invariants from './invariants.mjs';

const src = readFileSync(new URL('./election.spec.cjs', import.meta.url), 'utf-8');
const contract = JSON.parse(readFileSync(new URL('./contract.json', import.meta.url), 'utf-8'));
const dir = mkdtempSync(join(tmpdir(), 'election-mutants-'));

const MUTANTS = {
  'grant-to-anyone': ["granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);", 'granted = true;'],
  'revote-overwrites': ['if (granted) updated = { ...n, votedFor: candidate };', 'updated = { ...n, votedFor: candidate }; granted = true;'],
  'count-denied-replies': ["|| data.granted !== true) return unchanged('nodes');", ") return unchanged('nodes');"],
  // ('votes.length >= 1' would be equivalent: the count is only tested on a reply, when it is already 2.)
  'leader-on-timeout': ["{ role: 'candidate', term: TERM, votedFor: id, votes: [id] }", "{ role: 'leader', term: TERM, votedFor: id, votes: [id] }"],
  'announce-without-knowing-self': ["role: 'leader', leader: to }", "role: 'leader' }"],
  'leader-gives-a-vote': ["{ ...n, role: 'follower', term: TERM, votedFor: null, leader }", "{ ...n, role: 'follower', term: TERM, votedFor: leader, leader }"],
  'candidate-keeps-running': ["{ ...n, role: 'follower', leader }", "{ ...n, leader }"],
  'give-up-clears-vote': ["[id]: { ...model.nodes[id], role: 'follower' } };", "[id]: { ...model.nodes[id], role: 'follower', votedFor: null } };"],
  'gave-up-still-counts-replies': ["if (n.role !== 'candidate' || data.term !== n.term", "if (n.role === 'leader' || n.term !== TERM || data.term !== n.term"],
  'give-up-from-any-role': ["if (model.nodes[id].role !== 'candidate') return reject('give-up-only-candidate');", "if (model.nodes[id].term !== TERM) return reject('give-up-only-candidate');"],
  'timeout-anytime': ["if (n.role !== 'follower' || n.term !== 0) return reject('timeout-only-from-term0-follower');", "if (n.role === 'leader') return reject('timeout-only-from-term0-follower');"],
};

let failed = 0;
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!src.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const file = join(dir, `${name}.cjs`);
  writeFileSync(file, src.replace(from, to));
  const t0 = performance.now();
  const r = check({ specModule: loadSpec(file), contract, invariants, maxStates: 10000 });
  console.error(`  ${name}: ${r.statesExplored} states, ${Math.round(performance.now() - t0)} ms${r.error ? ', error: ' + r.error : ''}`);
  const names = [...new Set((r.violations || []).map((v) => v.invariant || v.name))];
  console.log(`${names.length ? 'caught ' : 'MISSED '} ${name}${names.length ? ': ' + names.join(', ') : ''}`);
  if (!names.length) failed++;
}
process.exit(failed ? 1 : 0);

